WITH filtered AS (SELECT id, customer_id, account_type, balance, status, DATE_TRUNC('MONTH', opened_date) opened_date_period FROM accounts WHERE opened_date >= TO_DATE('2023-06-04') AND status IS DISTINCT FROM 'CLOSED'), enriched AS (SELECT id, balance, status, opened_date_period, LAG(balance) OVER w_part prev_balance, ROW_NUMBER() OVER w_part event_seq, FIRST_VALUE(status, TRUE) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_status FROM filtered WHERE status NOT IN ('CLOSED', 'OPEN') WINDOW w_part AS (PARTITION BY status ORDER BY balance, id)), remaining_keys AS (SELECT status, id FROM enriched EXCEPT ALL SELECT status, id FROM accounts WHERE customer_id IN (14, 27, 28, 29)), verified AS (SELECT s.* FROM enriched s INNER JOIN remaining_keys k ON s.status = k.status AND s.id = k.id), eligible AS (SELECT s.* FROM verified s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time <= s.opened_date_period)) SELECT DATE_TRUNC('WEEK', opened_date_period) AS week_start, DATE_TRUNC('QUARTER', opened_date_period) AS quarter_start, PERCENTILE_APPROX(prev_balance, 0.5) AS prev_balance_p50, SUM(prev_balance) FILTER (WHERE status = 'CLOSED') AS closed_total_prev_balance, COUNT_IF(status = 'OPEN') AS open_events, STDDEV_SAMP(balance) AS balance_stddev, GROUPING_ID() AS gid FROM eligible GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', opened_date_period), DATE_TRUNC('QUARTER', opened_date_period)), (DATE_TRUNC('WEEK', opened_date_period)), ());
